CREATE TABLE IF NOT EXISTS sales (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NOT NULL, business_location_id INT NULL, customer_id INT NULL, invoice_no VARCHAR(50) NOT NULL, transaction_date DATETIME NOT NULL, status ENUM('final', 'draft', 'proforma') DEFAULT 'final', payment_status ENUM('paid', 'due', 'partial') DEFAULT 'due', total_before_tax DECIMAL(15,2) DEFAULT 0.00, tax_amount DECIMAL(15,2) DEFAULT 0.00, discount_amount DECIMAL(15,2) DEFAULT 0.00, final_total DECIMAL(15,2) DEFAULT 0.00, created_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
